import {operationDate,currentTimeZone,setTimeZone,validTimeZone} from './time.mjs';
import {escapeHtml as esc,id} from './core.mjs';
import {isReceiptDocument,RECEIPTS_FOLDER} from './documents-ui.mjs';
import {localToday} from './organizer.mjs';
import {CONTEXTS,documentContext,filterLibrary,validateDocumentMetadata,updateDocument,toggleDocumentFavorite,trashDocument,purgeDocument,saveExtractedText} from './library-core.mjs';
import {readUpload,downloadUpload} from './uploads.mjs';
import {extractDocumentText,originalFingerprint} from './extraction.mjs';

const button=(label,action,documentId='',style='outline',extra='')=>`<button type="button" class="${style}" data-action="library-${action}" ${documentId?`data-id="${esc(documentId)}"`:''} ${extra}>${label}</button>`;
const size=value=>value?`${Math.ceil(value/1024)} KB`:'';
export function createLibraryUI(ctx){
 const {getState,setState,save,toast,render,modal,closeModal,openDocument}=ctx;
 let filters={query:'',context:'all',category:'all',favorites:false,trashed:false},pending=null,controller=null,generation=0,submitting=false;
 const find=documentId=>getState().documents.find(d=>d.id===documentId);
 const fail=message=>{const target=document.querySelector('#library-error');if(target)target.textContent=message;else toast(message);};
 function cancelPending(){generation++;controller?.abort();controller=null;pending=null;submitting=false;}
 function commit(next,message){
  if(new TextEncoder().encode(JSON.stringify(next)).length>5000000){fail('Sua conta atingiu o limite atual de 5 MB. Exporte ou remova arquivos antes de continuar.');return false;}
  const previous=getState();setState(next);if(save()===false){setState(previous);fail('Não foi possível preparar o salvamento. Seus dados anteriores foram mantidos.');return false;}
  closeModal();render();toast(message+' Confira a confirmação de salvamento no topo.');return true;
 }
 const categoryOptions=(selected='Pessoal')=>[...new Set(['Casa','Trabalho','Pessoal','Finanças',...getState().documents.map(d=>d.category).filter(c=>typeof c==='string')])].map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('');
 function metadataFields(doc={}){return `<label for="library-title">Nome do documento</label><input id="library-title" name="title" value="${esc(doc.title||'')}" maxlength="160" required><div class="form-grid"><div><label for="library-context">Contexto</label><select id="library-context" name="context">${Object.entries(CONTEXTS).map(([key,label])=>`<option value="${key}" ${documentContext(doc)===key?'selected':''}>${label}</option>`).join('')}</select></div><div><label for="library-category">Categoria</label>${isReceiptDocument(doc)?`<input type="hidden" name="category" value="${esc(RECEIPTS_FOLDER)}"><input id="library-category" value="${esc(RECEIPTS_FOLDER)}" readonly>`:`<select id="library-category" name="category">${categoryOptions(doc.category)}</select>`}</div></div><label for="library-note">Anotação para encontrar depois (opcional)</label><textarea id="library-note" name="note" rows="3" maxlength="4000">${esc(doc.note||'')}</textarea>`;}
 function openCreate(){cancelPending();modal('Guardar um documento',`<p>Inclua um arquivo original ou crie uma referência sem arquivo. Pessoal e Empresa são espaços privados da mesma conta.</p><form id="library-create-form">${metadataFields()}<label for="library-upload">Original (opcional)</label><input id="library-upload" name="upload" type="file" accept="application/pdf,image/png,image/jpeg"><p class="small muted">PDF, PNG ou JPEG, até 500 KB. O texto poderá ser extraído e revisado depois de guardar.</p><p id="library-error" role="alert"></p><div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Guardar documento</button></div></form>`);}
 function editMetadata(doc){cancelPending();modal('Organizar documento',`<form id="library-edit-form" data-id="${esc(doc.id)}">${metadataFields(doc)}<p class="small muted">Editar o nome e a organização não altera o conteúdo do arquivo original nem do recibo já gerado.</p><p id="library-error" role="alert"></p><div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Salvar organização</button></div></form>`);}
 function reviewText(doc,result={text:doc.extractedText||'',method:'manual'}){
  pending={kind:'text',id:doc.id,fingerprint:originalFingerprint(doc),source:result};
  modal('Revise o texto de busca',`<p>Confira e corrija o texto antes de salvar. O reconhecimento pode trocar palavras, valores e nomes. Isso não cria tarefas, compromissos ou lançamentos.</p>${result.partial?`<p class="notice warm">Leitura parcial: páginas ${result.startPage||1} a ${result.endPage||result.pages} de ${result.totalPages}, com limite de 200.000 caracteres. Este texto não representa necessariamente todo o arquivo.</p>`:''}<form id="library-text-form" data-id="${esc(doc.id)}"><label for="library-extracted-text">Texto pesquisável</label><textarea class="library-text" id="library-extracted-text" name="text" rows="12" maxlength="200000">${esc(result.text)}</textarea><p id="library-error" role="alert"></p><div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Salvar texto revisado</button></div></form>`);
 }
 function extractionOptions(doc){cancelPending();pending={kind:'extract-options',id:doc.id};const pdf=doc.mime==='application/pdf'||doc.ext==='PDF';modal('Escolha como ler o documento',`<p>O arquivo será processado neste navegador. A leitura não altera o original e seu resultado precisa ser revisado.</p><form id="library-extract-form" data-id="${esc(doc.id)}">${pdf?'<div class="form-grid"><div><label for="library-first-page">Começar na página</label><input id="library-first-page" name="startPage" type="number" min="1" value="1" required></div><div><label for="library-page-count">Quantidade de páginas</label><input id="library-page-count" name="pageLimit" type="number" min="1" max="20" value="20" required></div></div><label class="library-check"><input name="ocr" type="checkbox" checked> Reconhecer páginas digitalizadas por OCR em português</label>':'<input name="ocr" type="hidden" value="on">'}${doc.extractedText?'<label class="library-check"><input name="append" type="checkbox"> Acrescentar ao texto já revisado, em vez de substituir</label>':''}<p class="small muted">Até 20 páginas por leitura e 200.000 caracteres de texto por documento. Para continuar um PDF maior, escolha a próxima página inicial e a opção de acrescentar.</p><p id="library-error" role="alert"></p><div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Iniciar leitura</button></div></form>`);}
 async function extract(doc,options={}){
  cancelPending();controller=new AbortController();const signal=controller.signal,version=generation,fingerprint=originalFingerprint(doc);
  modal('Lendo o documento',`<p>Extração e OCR em português são processados neste navegador, com bibliotecas hospedadas junto ao site. O arquivo não é enviado a um serviço de OCR. PDFs são lidos até 20 páginas por vez.</p><p id="library-progress" role="status">Preparando leitura…</p><p id="library-error" role="alert"></p><div class="modal-actions">${button('Cancelar leitura','close')}</div>`);
  try{const result=await extractDocumentText(doc,{...options,signal,onProgress:message=>{if(version===generation){const target=document.querySelector('#library-progress');if(target)target.textContent=message;}}});if(version!==generation||signal.aborted)return;const current=find(doc.id);if(!current||current.trashed||originalFingerprint(current)!==fingerprint)return;controller=null;if(options.append&&current.extractedText){const combined=current.extractedText+'\n\n'+result.text;result.text=combined.slice(0,200000);if(combined.length>200000)result.partial=true;}reviewText(current,result);}
  catch(error){if(version!==generation||error.name==='AbortError')return;controller=null;if(error.code==='PAGE_RANGE'){fail(error.message);return;}fail('Não foi possível ler o arquivo. PDFs protegidos, arquivos danificados ou limites deste aparelho podem impedir a leitura. Você ainda pode baixar o original ou inserir o texto manualmente.');const target=document.querySelector('#library-progress');if(target)target.textContent='Leitura não concluída.';}
 }
 function details(doc){cancelPending();if(openDocument(doc.id))return;modal(esc(doc.title),`<p>${esc(CONTEXTS[documentContext(doc)])} · ${esc(doc.category)} · ${esc(size(doc.fileSize))}</p>${doc.originalName?`<p class="small muted">Original: ${esc(doc.originalName)}</p>`:''}<p class="library-note">${esc(doc.note||'Sem anotação.')}</p>${doc.fileData||doc.pdfData?button('Baixar original','download',doc.id,'primary'):'<p>Referência sem arquivo anexado.</p>'}<div class="library-detail-actions">${button('Editar organização','edit',doc.id)}${doc.fileData||doc.pdfData?button('Extrair texto / OCR','extract',doc.id):''}${button('Editar texto de busca','text',doc.id)}</div>${doc.extractedText?`<details><summary>Ver texto pesquisável</summary><pre class="library-text-preview">${esc(doc.extractedText)}</pre></details>`:''}${doc.sha256?`<p class="small muted library-hash">Integridade SHA-256: ${esc(doc.sha256)}</p>`:''}`);}
 function renderPage(receipts=false){
  const documents=getState().documents,results=filterLibrary(documents,{...filters,receipts}),categories=[...new Set(documents.map(d=>d.category).filter(c=>typeof c==='string'))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  return `<section class="document-create-banner"><div><span class="eyebrow">DOCUMENTOS + RECIBOS</span><h2>Seus documentos, no lugar.</h2><p>Guarde originais, organize seus contextos e encontre palavras no texto revisado.</p></div><a class="primary" href="#/vida/documentos/criar">Criar recibo ou comprovante</a></section><nav class="document-folder-nav" aria-label="Biblioteca"><a class="filter ${receipts?'':'selected'}" href="#/vida/documentos">Todos os documentos</a><a class="filter ${receipts?'selected':''}" href="#/vida/documentos/recibos">Recibos e comprovantes</a></nav><section class="card"><div class="section-head"><div><h2>${filters.trashed?'Lixeira':receipts?'Recibos e comprovantes':'Documentos, sem a procura.'}</h2><p class="muted small">${results.length} ${results.length===1?'documento encontrado':'documentos encontrados'} · privados da sua conta</p></div>${button('+ Guardar documento','add','','primary small-button')}</div><div class="library-contexts" role="group" aria-label="Contextos privados">${[['all','Todos'],...Object.entries(CONTEXTS)].map(([key,label])=>button(label,'context','','filter '+(filters.context===key?'selected':''),`data-context="${key}" aria-pressed="${filters.context===key}"`)).join('')}${button('★ Favoritos','favorites','','filter '+(filters.favorites?'selected':''),`aria-pressed="${filters.favorites}"`)}</div><div class="document-toolbar library-toolbar"><label class="search-field"><input id="library-search" type="search" maxlength="200" placeholder="Nome, anotação ou texto do documento" aria-label="Buscar nos documentos" value="${esc(filters.query)}"></label><select id="library-category-filter" aria-label="Filtrar categoria"><option value="all">Todas as categorias</option>${categories.map(c=>`<option value="${esc(c)}" ${filters.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><div class="library-filter-actions">${button(filters.trashed?'Voltar à biblioteca':'Lixeira','trash-toggle')}${button('Limpar filtros','clear','','text-link')}</div></div>${filters.trashed?'<p class="notice">Documentos nesta lixeira podem ser restaurados. A exclusão definitiva exige confirmação e remove também o texto de busca.</p>':''}<div class="document-grid">${results.map(doc=>`<article class="document-card"><div class="document-top"><span class="file-icon">${esc(doc.ext||'TXT')}</span><span class="badge">${esc(CONTEXTS[documentContext(doc)])}</span></div><h3>${esc(doc.title)}</h3><p>${esc(doc.category)} · ${esc(doc.date||'')}</p><small>${doc.extractedText?'Texto pesquisável revisado':doc.fileData||doc.pdfData?'Original disponível':'Referência sem arquivo'}</small><div class="library-card-actions">${filters.trashed?`${button('Restaurar','restore',doc.id)}${button('Excluir definitivamente','request-purge',doc.id,'text-link danger')}`:`${button('Abrir','open',doc.id,'text-link')}${button(doc.favorite?'★ Favorito':'☆ Favoritar','favorite',doc.id,'text-link',`aria-pressed="${doc.favorite===true}"`)}${button('Organizar','edit',doc.id,'text-link')}${doc.fileData||doc.pdfData?button('Extrair texto','extract',doc.id,'text-link'):''}${button('Texto de busca','text',doc.id,'text-link')}${doc.fileData||doc.pdfData?`<button type="button" class="text-link" data-action="share-open" data-id="${esc(doc.id)}">Links privados</button>`:''}${button('Mover para lixeira','trash',doc.id,'text-link')}`}</div></article>`).join('')}</div>${results.length?'':'<div class="empty"><h3>Nenhum documento por aqui.</h3><p>Guarde um arquivo ou ajuste os filtros para encontrar o que precisa.</p></div>'}</section><p class="small muted">Pessoal e Empresa organizam seus próprios documentos. Isso não concede acesso a outras pessoas. A busca inclui somente os documentos da sua conta; OCR precisa de revisão.</p>`;
 }
 function handleClick(action,data){
  if(!action.startsWith('library-'))return false;const key=action.slice(8),doc=find(data.id);
  try{
   if(key==='close')closeModal();
   else if(key==='add')openCreate();
   else if(key==='context'&&['all','personal','business'].includes(data.context)){filters.context=data.context;render();}
   else if(key==='favorites'){filters.favorites=!filters.favorites;render();}
   else if(key==='trash-toggle'){filters.trashed=!filters.trashed;render();}
   else if(key==='clear'){filters={query:'',context:'all',category:'all',favorites:false,trashed:filters.trashed};render();}
   else if(doc){
    if(key==='restore')commit(trashDocument(getState(),doc.id,false),'Restauração preparada.');
    else if(key==='trash')commit(trashDocument(getState(),doc.id,true),'Documento movido para a lixeira.');
    else if(key==='request-purge'&&doc.trashed){cancelPending();pending={kind:'purge',id:doc.id};modal('Excluir este documento definitivamente?',`<p><b>${esc(doc.title)}</b></p><p>O arquivo e seu texto de busca serão removidos do acervo da conta. A ação não pode ser desfeita pelo aplicativo. Lançamentos financeiros são preservados e referências em consultas serão desvinculadas.</p><p class="small muted">Cópias de segurança da hospedagem podem permanecer até expirar sua retenção.</p><p id="library-error" role="alert"></p><div class="modal-actions">${button('Voltar','close')}${button('Excluir definitivamente','confirm-purge',doc.id,'primary')}</div>`);}
    else if(key==='confirm-purge'&&pending?.kind==='purge'&&pending.id===doc.id&&doc.trashed)commit(purgeDocument(getState(),doc.id),'Exclusão preparada.');
    else if(!doc.trashed){if(key==='open')details(doc);else if(key==='edit')editMetadata(doc);else if(key==='favorite')commit(toggleDocumentFavorite(getState(),doc.id),'Favorito atualizado.');else if(key==='download')downloadUpload(doc);else if(key==='extract')extractionOptions(doc);else if(key==='text'){cancelPending();reviewText(doc);}}
   }
  }catch(error){fail(error.message);}return true;
 }
 function handleSubmit(form){if(!form.id.startsWith('library-'))return false;if(!form.checkValidity()){form.reportValidity();return true;}if(submitting)return true;const raw=Object.fromEntries(new FormData(form));
  if(form.id==='library-create-form'){
   let metadata;try{metadata=validateDocumentMetadata(raw);}catch(error){fail(error.message);return true;}
   submitting=true;const version=generation,submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;
   void (async()=>{try{const original=await readUpload(raw.upload);if(version!==generation)return;const doc={id:id(),...metadata,date:localToday(),createdAt:new Date().toISOString(),ext:'TXT',trashed:false,favorite:false,...original,...(original?{originalName:raw.upload.name}:{})};if(commit({...getState(),documents:[doc,...getState().documents]},'Documento incluído na biblioteca.')){filters.trashed=false;render();}}catch(error){if(version===generation)fail(error.message);}finally{if(version===generation){submitting=false;if(submit?.isConnected)submit.disabled=false;}}})();
  }else if(form.id==='library-edit-form'){try{commit(updateDocument(getState(),form.dataset.id,raw),'Organização atualizada.');}catch(error){fail(error.message);}}
  else if(form.id==='library-extract-form'&&pending?.kind==='extract-options'&&pending.id===form.dataset.id){const doc=find(pending.id);if(doc&&!doc.trashed)void extract(doc,{ocr:raw.ocr==='on',startPage:Number(raw.startPage||1),pageLimit:Number(raw.pageLimit||20),append:raw.append==='on'});}
  else if(form.id==='library-text-form'&&pending?.kind==='text'&&pending.id===form.dataset.id){const doc=find(pending.id);if(!doc||doc.trashed||originalFingerprint(doc)!==pending.fingerprint){fail('O arquivo mudou. Abra a leitura novamente antes de salvar.');return true;}try{commit(saveExtractedText(getState(),doc.id,raw.text,pending.source),'Texto de busca atualizado.');}catch(error){fail(error.message);}}
  return true;
 }
 function handleInput(event){if(event.target.id!=='library-search')return false;filters.query=event.target.value;const position=event.target.selectionStart;render();const field=document.querySelector('#library-search');field?.focus();try{field?.setSelectionRange(position,position);}catch{}return true;}
 function handleChange(event){if(event.target.id!=='library-category-filter')return false;filters.category=event.target.value;render();document.querySelector('#library-category-filter')?.focus();return true;}
 return {renderPage,openCreate,handleClick,handleSubmit,handleInput,handleChange,cancelPending};
}
